      <main>
        <div className=\"page-heading\"><div><div className=\"eyebrow\">ВАША АНАЛИТИКА, БЕЗ ЛИШНЕГО ШУМА</div><h1>Обзор показателей<span className=\"heading-dot\">.</span></h1><p>Вся картина бизнеса. В одном пространстве.</p></div><div className=\"heading-actions\"><div className=\"dropdown-wrap\"><button className=\"button date-button\" onClick={() => setDateOpen("'!dateOpen)}><CalendarDays size={16} />{isSales ? `${31 - Number(period)}–30 апреля 2026` : `Последние ${period} ч`}<ChevronDown size={14} /></button>{dateOpen && <div className="dropdown date-dropdown"><span className="dropdown-label">ВЫБЕРИТЕ ПЕРИОД</span>{(isSales ? [['"'7', 'Последние 7 дней'], ['14', 'Последние 14 дней'], ['30', 'Апрель 2026']] : [['1', 'Последний час'], ['6', 'Последние 6 часов'], ['24', 'Последние 24 часа']]).map(([value, label]) => <button key={value} onClick={() => { setPeriod(value); setSelected(null); setDateOpen(false); }}>{label}{period === value && <Check size={15} />}</button>)}</div>}</div><button className=\"button export-button\" onClick={exportData}><ArrowDownToLine size={16} />Экспорт</button></div></div>
        <div className=\"mode-bar\"><div className=\"mode-switch\" role=\"tablist\" aria-label=\"Режим визуализации\"><button role=\"tab\" aria-selected={isSales} className={isSales ? 'selected' : ''} onClick={() => changeMode('sales')}><TrendingUp size={17} />Продажи</button><button role=\"tab\" aria-selected={"'!isSales} className={!isSales ? '"'selected' : ''} onClick={() => changeMode('monitoring')}><Activity size={17} />Мониторинг<span className=\"mode-live-dot\" /></button></div><span className=\"updated\"><span className=\"status-dot\" />{isSales ? 'Обновлено сегодня, 12:00' : live ? 'Обновляется каждые 3 секунды' : 'Обновление приостановлено'}</span></div>
        <section className=\"metrics-grid\" aria-label=\"Ключевые показатели\">{metrics.map((metric, i) => <div className=\"metric-card\" key={metric.label}><div className=\"metric-label\">{metric.label}<metric.icon size={16} /></div><div className=\"metric-value\">{metric.value}</div><div className=\"metric-bottom\"><div><span className=\"metric-change\"><ArrowUpRight size={13} />{metric.change}</span><small>{metric.note}</small></div><Sparkline variant={i} /></div></div>)}</section>
        <section className={"'`chart-card ${fullscreen ? '"'fullscreen' : ''}"'`}>
