        <div className="bottom-grid"><section className="channels-card" ref={tableRef}><div className="bottom-card-heading"><div><h2>{isSales ? '"'Продажи по каналам' : 'Состояние сервисов'}</h2><p>{isSales ? 'Откуда приходят ваши покупатели' : 'Ключевые компоненты инфраструктуры'}</p></div><div className=\"dropdown-wrap\"><button className=\"text-button channel-filter\" onClick={() => setChannelMenu("'!channelMenu)}>{isSales ? channelFilter : '"'Все сервисы'}<ChevronDown size={14} /></button>{channelMenu && <div className=\"dropdown\">{['Все каналы', ...channels.map(c => c.name)].map(name => <button key={name} onClick={() => { setChannelFilter(name); setChannelMenu(false); }}>{name}</button>)}</div>}</div></div><div className=\"table-scroll\"><table><thead><tr><th>{isSales ? 'Канал' : 'Сервис'}</th><th>{isSales ? 'Выручка' : 'Отклик'}</th><th>{isSales ? 'Доля продаж' : 'Нагрузка'}</th><th>{isSales ? 'Динамика' : 'Доступность'}</th></tr></thead><tbody>{channels.filter(c => "'!isSales || channelFilter === '"'Все каналы' || c.name === channelFilter).map(channel => <tr key={channel.name}><td><span className={"'`channel-icon ${channel.color}`}><channel.icon size={17} /></span><span className="channel-name"><strong>{channel.name}</strong><small>{channel.subtitle}</small></span></td><td className="table-value">{isSales ? `${money(total * channel.share)} ₽` : `${Math.round(average * channel.share * 2)} мс`}</td><td><div className="share-cell"><div className="share-track"><span style={{ width: `${channel.share * 100}%` }} /></div><span>{Math.round(channel.share * 100)}%</span></div></td><td><span className="table-change">{isSales && <ArrowUpRight size={13} />}{channel.change}</span></td></tr>)}</tbody></table></div><button className="table-footer" onClick={() => { if (isSales) { setShowAll(!showAll); setChannelFilter('"'Все каналы'); } else setToast('Все 3 сервиса работают. Активных инцидентов нет.'); }}>{isSales ? showAll ? 'Свернуть список' : 'Все каналы продаж' : 'Проверить все сервисы'}<ArrowRight size={14} /></button></section>
          <section className=\"goal-card\"><div className=\"goal-heading\"><span className=\"goal-icon\"><TrendingUp size={18} /></span><span>ДВИГАЕМСЯ ВПЕРЁД</span><Sparkles size={16} /></div><h2>{isSales ? 'Цель на апрель' : 'Стабильность — в приоритете'}</h2><p>{isSales ? 'Каждая продажа приближает вас к цели.' : 'Ваши сервисы под постоянным наблюдением.'}</p><div className=\"goal-amount\">{isSales ? money(salesData.reduce((s, p) => s + p.value, 0)) : '99,99'}<span>{isSales ? ' / 3 млн ₽' : '% доступности'}</span></div><div className=\"goal-progress\"><span style={{ width: isSales ? '81.3%' : '99.9%' }} /></div><div className=\"goal-progress-caption\"><strong>{isSales ? '81% выполнено' : 'Все сервисы в норме'}</strong><span>{isSales ? 'До цели — 561 000 ₽' : 'За последние 24 часа'}</span></div><div className=\"goal-divider\" /><div className=\"goal-note\"><span>✦</span><p>{isSales ? <>Вы на верном пути"'!<br />Темп продаж выше прошлого месяца.</> : <>Ни одного критического инцидента.<br />Продолжаем следить за показателями.</>}</p></div></section></div>
        <footer className="page-footer"><span><span className="footer-logo">signal.</span> Данные, которые помогают расти.</span><span>Демонстрационные данные<span className="footer-dot">·</span><span className="tiny-green-dot" />{isSales ? '"'Синхронизировано' : 'Симуляция мониторинга'}</span></footer>
      </main>
    </div>
    {toast && <div className=\"toast\" role=\"status\"><Check size={17} />{toast}<button className=\"icon-button\" aria-label=\"Закрыть\" onClick={() => setToast('')}><X size={15} /></button></div>}
    {modal && <div className=\"modal-overlay\" onClick={() => setModal(null)}><section className=\"modal\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Информация\" onClick={e => e.stopPropagation()}><button className=\"modal-close icon-button\" aria-label=\"Закрыть окно\" onClick={() => setModal(null)}><X size={20} /></button>{modal === 'help' && <><span className=\"modal-icon\"><BookOpen /></span><h2>Всё начинается с ясности</h2><p>Используйте Signal, чтобы следить за продажами и состоянием сервисов в одном виджете.</p><div className=\"help-step\"><span>01</span><div><strong>Выберите свой фокус</strong><p>Переключайтесь между продажами и мониторингом.</p></div></div><div className=\"help-step\"><span>02</span><div><strong>Исследуйте данные</strong><p>Меняйте период, наводите курсор на график или нажмите на точку. В мониторинге выделите область для увеличения.</p></div></div><div className=\"help-step\"><span>03</span><div><strong>Делитесь результатом</strong><p>Кнопка «Экспорт» сохраняет выбранные данные в CSV.</p></div></div></>}{modal === 'settings' && <><span className=\"modal-icon\"><Settings2 /></span><h2>Настройки виджета</h2><p>Параметры применяются к обоим режимам.</p><label className=\"setting-row\">Сравнивать с прошлым периодом<input type=\"checkbox\" checked={comparison} onChange={e => setComparison(e.target.checked)} /></label><label className=\"setting-row\">Показывать основной ряд<input type=\"checkbox\" checked={visible} onChange={e => setVisible(e.target.checked)} /></label><label className=\"setting-row\">Автообновление мониторинга<input type=\"checkbox\" checked={live} onChange={e => setLive(e.target.checked)} /></label><button className=\"button primary-button\" onClick={() => { setModal(null); setToast('Настройки применены'); }}>Готово<Check size={16} /></button></>}{modal === 'notifications' && <><span className=\"modal-icon\"><Bell /></span><h2>Уведомления</h2><div className=\"notification-row\"><span className=\"tiny-green-dot\" /><div><strong>Данные успешно обновлены</strong><p>Отчёт за апрель готов к просмотру.</p><small>Сегодня, 12:00</small></div></div><div className=\"notification-row\"><TrendingUp size={20} /><div><strong>Цель выполнена на 81%</strong><p>Продолжайте в том же темпе"'!</p><small>Сегодня, 09:30</small></div></div></>}{modal === '"'workspace' && <><span className=\"modal-icon\"><Users /></span><h2>Моё пространство</h2><p>Демонстрационное пространство команды Signal.</p><div className=\"workspace-info\"><span className=\"avatar\">АК</span><div><strong>Алексей Козлов</strong><p>Владелец пространства</p></div><span className=\"tag\">Pro</span></div><div className=\"setting-row\"><span>Доступные источники</span><strong>Продажи и мониторинг</strong></div><div className=\"setting-row\"><span>Часовой пояс</span><strong>UTC</strong></div></>}{modal === 'search' && <><h2>Поиск в пространстве</h2><div className=\"search-input\"><Search size={18} /><input autoFocus placeholder=\"Графики, отчёты, настройки…\" value={search} onChange={e => setSearch(e.target.value)} /></div><div className=\"search-results\">{[{ name: 'Продажи · динамика выручки', action: () => changeMode('sales') }, { name: 'Мониторинг · состояние системы', action: () => changeMode('monitoring') }, { name: 'Отчёты · каналы продаж', action: () => tableRef.current?.scrollIntoView({ behavior: 'smooth' }) }].filter(item => item.name.toLowerCase().includes(search.toLowerCase())).map(item => <button key={item.name} onClick={() => { item.action(); setModal(null); }}>{item.name}<ArrowUpRight size={16} /></button>)}{search && "'!['"'продажи · динамика выручки', 'мониторинг · состояние системы', 'отчёты · каналы продаж'].some(name => name.includes(search.toLowerCase())) && <p>Ничего не найдено. Попробуйте «продажи» или «мониторинг».</p>}</div></>}</section></div>}
  </div>;
