/bin/bash -lc "cat > __agent_eval__/verify.mjs <<'EOF'
import { chromium } from '@playwright/test';
import assert from 'node:assert/strict';
const browser = await chromium.launch({executablePath:'/home/node/.cache/ms-playwright/chromium-1248/chrome-linux-arm64/chrome', headless: true, args:['--no-sandbox']});
const page = await browser.newPage({ viewport: {width:1440,height:1080}, deviceScaleFactor:1 });
const errors=[];const requests=[];
page.on('pageerror', e=>errors.push(e.message));
page.on('request',r=>requests.push(r.url()));
await page.goto('http://localhost:4173');
await page.locator('.recharts-area').waitFor();
await page.waitForTimeout(900);
assert(requests.some(x=>x.includes('SalesEngine-')),'sales engine loads');
assert("'!requests.some(x=>x.includes('"'MonitoringEngine-')),'monitor engine is deferred');
await page.screenshot({path:'/tmp/signal-desktop.png',fullPage:true});
await page.getByRole('button',{name:'7 дней',exact:true}).click();
assert.equal(await page.locator('.metric-value').first().innerText(),'788 000 ₽');
await page.locator('.compare-label input').uncheck();
assert.equal(await page.locator('.recharts-line').count(),0);
await page.locator('.compare-label input').check();
const downloadPromise=page.waitForEvent('download');
await page.getByRole('button',{name:'Экспорт',exact:true}).click();
const download=await downloadPromise;
assert.equal(download.suggestedFilename(),'sales-7.csv');
await page.getByRole('tab',{name:'Мониторинг'}).click();
await page.locator('.uplot canvas').first().waitFor();
assert(requests.some(x=>x.includes('MonitoringEngine-')),'monitor engine loads on demand');
await page.getByRole('button',{name:'В эфире'}).click();
await page.getByRole('button',{name:'1 час',exact:true}).click();
assert.equal(await page.locator('.metric-value').last().innerText(),'60');
await page.screenshot({path:'/tmp/signal-monitor.png',fullPage:true});
await page.getByRole('button',{name:'Развернуть график'}).click();
assert(await page.locator('.fullscreen').isVisible());
await page.keyboard.press('Escape');
assert.equal(await page.locator('.fullscreen').count(),0);
await page.getByRole('tab',{name:'Продажи',exact:true}).click();
await page.locator('.recharts-area').waitFor();
await page.setViewportSize({width:390,height:844});
await page.screenshot({path:'/tmp/signal-mobile.png',fullPage:true});
assert(await page.evaluate(()=>document.documentElement.scrollWidth <= window.innerWidth),'no mobile page overflow');
await page.getByRole('button',{name:'Поиск',exact:true}).click();
await page.getByPlaceholder('Графики, отчёты, настройки…').fill('мониторинг');
await page.getByRole('button',{name:'Мониторинг · состояние системы'}).click();
await page.locator('.uplot canvas').first().waitFor();
assert.equal(errors.length,0,errors.join('\\n'));
console.log('PASS: lazy loading, periods, comparison, CSV export, monitoring, fullscreen, search, mobile overflow; no browser errors.');
await browser.close();
EOF
node __agent_eval__/verify.mjs"

