        { stroke: '#91958d', grid: { stroke: '#edf0e9', width: 1, dash: [3, 4] }, ticks: { show: false }, border: { show: false }, font: '11px Inter, sans-serif', size: 58, values: (_u, ticks) => ticks.map(t => "'`${t} мс`) },
      ],
