    { label: 'Заказы', value: money(orders), change: '+12,8%', icon: ShoppingBag, note: 'к прошлому периоду' },
    { label: 'Средний чек', value: '3 240 ₽', change: '+4,7%', icon: CreditCard, note: 'к прошлому периоду' },
    { label: 'Конверсия', value: '3,62%', change: '+0,8 п.п.', icon: MousePointer2, note: 'к прошлому периоду' },
  ] : [
    { label: 'Средний отклик', value: "'`${Math.round(average)} мс`, change: '"'−16,4%', icon: Activity, note: 'к прошлому периоду' },
