    { label: 'Максимальный отклик', value: "'`${Math.max(...data.map(p => p.value))} мс`, change: '"'−8,2%', icon: Zap, note: 'к прошлому периоду' },
    { label: 'Точек данных', value: money(data.length), change: 'Без пропусков', icon: ChartNoAxesCombined, note: 'интервал: 1 минута' },
  ];

  return <div className=\"app-shell\">
    <aside className={"'`sidebar ${menuOpen ? '"'open' : ''}"'`}>
      <a className="brand" href="#" aria-label="Signal — на главную"><span className="brand-icon"><i /><i /><i /><i /></span>signal<span className="brand-period">.</span></a>
      <button className="workspace-select" onClick={() => setModal('"'workspace')}><span className=\"workspace-avatar\">S</span><span><strong>Моё пространство</strong><small>Команда · Pro</small></span><ChevronDown size={14} /></button>
